#include <bits/stdc++.h>
using namespace std;

int main() {
    vector<int> x(6);
    int total = 0;
    for (int i = 0; i < 6; i++) {
        cin >> x[i];
        total += x[i];
    }

    if (total % 3 != 0) {
        cout << 'N' << '\n';
        return 0;
    }

    int target = total / 3;

    for (int i = 0; i < 6; i++) {
        if (x[i] != target) continue;

        for (int j = 0; j < 6; j++) {
            if (j == i) continue;
            for (int k = j + 1; k < 6; k++) {
                if (k == i) continue;
                if (x[j] + x[k] == target) {
                    cout << 'S' << '\n';
                    return 0;
                }
            }
        }
    }

    cout << 'N' << '\n';
    return 0;
}
